package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.time.LocalDate; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class ReconciliationService{private final LedgerRepository ledgers;private final AccountRepository accounts;private final ReconciliationRepository reconciliations;public ReconciliationService(LedgerRepository l,AccountRepository a,ReconciliationRepository r){ledgers=l;accounts=a;reconciliations=r;}public Mono<ReconciliationView> create(UUID a,UUID l,CreateReconciliationRequest q){return own(a,l).flatMap(x->accounts.findById(q.accountId()).filter(ac->ac.ownerId().equals(a)&&ac.ledgerId().equals(l)).switchIfEmpty(Mono.error(new NotFoundException("Account 不存在或不属于该 Ledger"))).flatMap(ac->{BigDecimal difference=q.statementBalance().subtract(ac.currentBalance());ReconciliationStatus status=difference.signum()==0?ReconciliationStatus.MATCHED:ReconciliationStatus.DIFFERENCE;Instant n=Instant.now();return reconciliations.save(new ReconciliationEntity(null,l,q.accountId(),a,q.statementDate(),q.statementBalance(),ac.currentBalance(),difference,status,q.note(),n,n,null));})).map(this::view);}public Flux<ReconciliationView> list(UUID a,UUID l){return own(a,l).flatMapMany(x->reconciliations.findAllByLedgerIdAndOwnerIdOrderByStatementDateDesc(l,a).map(this::view));}public Mono<ReconciliationView> close(UUID a,UUID id){return reconciliations.findById(id).filter(r->r.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Reconciliation 不存在或无权访问"))).flatMap(r->{if(r.status()==ReconciliationStatus.OPEN)return Mono.error(new ConflictException("Open 对账不能直接关闭"));return reconciliations.save(new ReconciliationEntity(r.id(),r.ledgerId(),r.accountId(),r.ownerId(),r.statementDate(),r.statementBalance(),r.calculatedBalance(),r.difference(),ReconciliationStatus.CLOSED,r.note(),r.createdAt(),Instant.now(),r.version()));}).map(this::view);}private Mono<LedgerEntity> own(UUID a,UUID id){return ledgers.findById(id).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private ReconciliationView view(ReconciliationEntity r){return new ReconciliationView(r.id(),r.accountId(),r.statementDate(),r.statementBalance(),r.calculatedBalance(),r.difference(),r.status(),r.note(),r.createdAt());}}
